const target = $('Validate & Normalize').item.json.target;
const lines = ($json.stdout || '').split('\n');
const records = { A: [], AAAA: [], MX: [], NS: [], TXT: [], SOA: [] };
let section = null;
for (const line of lines) {
  const t = line.trim();
  if (!t) continue;
  const marker = t.match(/^(A|AAAA|MX|NS|TXT|SOA):$/);
  if (marker) { section = marker[1]; continue; }
  if (section && records[section]) records[section].push(t);
}
return [{ json: { target, records } }];

const dnsInfo = $('Parse DNS').item.json;
const norm = $('Validate & Normalize').item.json;
let subdomains = [];
if (!norm.isIp) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://crt.sh/?q=%25.${encodeURIComponent(norm.target)}&output=json`,
      timeout: 15000, json: true,
    });
    const arr = Array.isArray(res) ? res : [];
    const set = new Set();
    for (const entry of arr) {
      if (entry && entry.name_value) entry.name_value.split('\n').forEach(n => set.add(n.trim().toLowerCase()));
    }
    subdomains = Array.from(set);
  } catch (e) { subdomains = []; }  // crt.sh has no SLA - a 502/timeout is not fatal
}

let whoisText = '';
try { whoisText = $('WHOIS Lookup').item.json.stdout || ''; } catch (e) { whoisText = ''; }
const whoisFields = {};
for (const line of whoisText.split('\n')) {
  const m = line.match(/^\s*(Registrar|Registrant Organization|Creation Date|Registry Expiry Date|Name Server|Updated Date)\s*:\s*(.+)$/i);
  if (m) {
    const key = m[1].trim();
    whoisFields[key] = whoisFields[key] ? [].concat(whoisFields[key], m[2].trim()) : m[2].trim();
  }
}

const resolvedIp = norm.isIp ? norm.target : ((dnsInfo.records.A && dnsInfo.records.A[0]) || null);

const attckCoverage = [
  { technique: 'T1590.002', name: 'Gather Victim Network Information: DNS', status: 'executed' },
  { technique: 'T1596.003', name: 'Search Open Technical Databases: Digital Certificates', status: subdomains.length || !norm.isIp ? 'executed' : 'skipped (IP target, no hostname to query)' },
  { technique: 'T1596.002', name: 'Search Open Technical Databases: WHOIS', status: whoisText ? 'executed' : 'no data returned' },
];

return [{ json: {
  target: norm.target, isIp: norm.isIp, scanIntensity: norm.scanIntensity,
  dns: dnsInfo.records, subdomains, whois: whoisFields, resolvedIp, attckCoverage
} }];

const ctx = $('Parse Attribution').item.json;
const xml = $json.stdout || '';
const ports = [];
const portBlockRe = /<port protocol="(\w+)" portid="(\d+)">([\s\S]*?)<\/port>/g;
let pm;
while ((pm = portBlockRe.exec(xml)) !== null) {
  const [, protocol, portid, block] = pm;
  const stateMatch = block.match(/<state state="(\w+)"/);
  if (!stateMatch || stateMatch[1] !== 'open') continue;
  const serviceTagMatch = block.match(/<service\b[^>]*\/?>/);
  let service = 'unknown', product = null, version = null;
  if (serviceTagMatch) {
    const tag = serviceTagMatch[0];
    service = (tag.match(/name="([^"]*)"/) || [])[1] || 'unknown';
    product = (tag.match(/product="([^"]*)"/) || [])[1] || null;
    version = (tag.match(/version="([^"]*)"/) || [])[1] || null;
  }
  const scripts = [];
  const scriptRe = /<script id="([^"]*)"[^>]*output="([^"]*)"[^>]*>([\s\S]*?)<\/script>|<script id="([^"]*)"[^>]*output="([^"]*)"\s*\/>/g;
  let sm;
  while ((sm = scriptRe.exec(block)) !== null) {
    const id = sm[1] || sm[4];
    const rawOutput = sm[2] || sm[5];
    const inner = sm[3] || '';
    const cleanOutput = rawOutput.replace(/&#10;/g, ' ').replace(/&quot;/g, '"').replace(/&amp;/g, '&').trim().slice(0, 300);
    if (id === 'vulners') {
      const cves = [];
      // <elem> field order inside each vulners <table> block is not
      // guaranteed (observed cvss,type,id,is_exploit against a real target,
      // not the is_exploit,cvss,id,type order this originally assumed) -
      // parse each inner <table>...</table> block into a key/value map
      // instead of matching a fixed sequence, order-independent.
      const innerTableRe = /<table>([\s\S]*?)<\/table>/g;
      const elemRe = /<elem key="([^"]+)">([^<]*)<\/elem>/g;
      let vm;
      while ((vm = innerTableRe.exec(inner)) !== null) {
        const fields = {};
        elemRe.lastIndex = 0;
        let em;
        while ((em = elemRe.exec(vm[1])) !== null) fields[em[1]] = em[2];
        if (fields.id && fields.cvss) {
          cves.push({ id: fields.id, type: fields.type || 'unknown', cvss: Number(fields.cvss), isExploit: fields.is_exploit === 'true' });
        }
      }
      if (cves.length) scripts.push({ id, output: cleanOutput, cves });
      continue;
    }
    scripts.push({ id, output: cleanOutput });
  }
  ports.push({ port: Number(portid), protocol, service, product, version, scripts });
}
const coverage = [...ctx.attckCoverage, { technique: 'T1595.001/.002', name: 'Active Scanning: Scanning IP Blocks / Vulnerability Scanning', status: 'executed' }];
return [{ json: { ...ctx, attckCoverage: coverage, portScan: { skipped: false, openPorts: ports } } }];

const ctx = $json;
const coverage = [...ctx.attckCoverage, { technique: 'T1595.001/.002', name: 'Active Scanning: Scanning IP Blocks / Vulnerability Scanning', status: 'skipped (scanIntensity=dns-only or no resolvable IP)' }];
return [{ json: { ...ctx, attckCoverage: coverage, portScan: { skipped: true, reason: 'scanIntensity=dns-only or no resolvable IP' } } }];

const ctx = $json;
const target = ctx.target;
const maxPages = 10;
const maxDepth = 2;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const politeDelay = () => sleep(400 + Math.floor(Math.random() * 500));
const visited = new Set();
const fetchUrl = async (url) => {
  try {
    await politeDelay();
    return await this.helpers.httpRequest({ method: 'GET', url, timeout: 10000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  } catch (e) { return null; }
};

const getOrigin = (u) => u.endsWith('/') ? u.slice(0, -1) : u;
const resolveHref = (href, baseUrl, origin) => {
  if (/^https?:\/\//i.test(href)) return href;
  if (href.startsWith('//')) return (origin.startsWith('https') ? 'https:' : 'http:') + href;
  if (href.startsWith('/')) return origin + href;
  const baseDir = baseUrl.slice(0, baseUrl.lastIndexOf('/') + 1);
  return baseDir + href;
};

const openPorts = (ctx.portScan && !ctx.portScan.skipped) ? ctx.portScan.openPorts.map(p => p.port) : [];
const candidateUrls = [];
if (openPorts.includes(443)) candidateUrls.push(`https://${target}/`);
if (openPorts.includes(80)) candidateUrls.push(`http://${target}/`);
for (const p of openPorts) {
  if (p !== 80 && p !== 443) candidateUrls.push(`http://${target}:${p}/`);
}

let startUrl = null, homepage = null;
if (candidateUrls.length === 0) {
  const coverage = [...ctx.attckCoverage, { technique: 'T1594', name: 'Search Victim-Owned Websites', status: 'no open ports discovered to attempt a web scan against' }];
  return [{ json: { ...ctx, attckCoverage: coverage, webScan: { skipped: false, reachable: false, reason: 'no open ports from port scan' } } }];
}
for (const url of candidateUrls) {
  homepage = await fetchUrl(url);
  if (homepage) { startUrl = url; break; }
}
if (!homepage) {
  const coverage = [...ctx.attckCoverage, { technique: 'T1594', name: 'Search Victim-Owned Websites', status: 'attempted, target unreachable' }];
  return [{ json: { ...ctx, attckCoverage: coverage, webScan: { skipped: false, reachable: false, portsTried: candidateUrls } } }];
}
const origin = getOrigin(startUrl);

const SECURITY_HEADERS = [
  'strict-transport-security', 'content-security-policy', 'x-frame-options',
  'x-content-type-options', 'referrer-policy', 'permissions-policy',
];
const auditHeaders = (headers) => {
  const present = {}, missing = [];
  for (const h of SECURITY_HEADERS) {
    if (headers[h]) present[h] = headers[h];
    else missing.push(h);
  }
  return { present, missing };
};

const auditCookies = (headers) => {
  let raw = headers['set-cookie'];
  if (!raw) return [];
  if (!Array.isArray(raw)) raw = [raw];
  return raw.map((c) => {
    const name = c.split('=')[0];
    return {
      name,
      secure: /;\s*Secure/i.test(c),
      httpOnly: /;\s*HttpOnly/i.test(c),
      sameSite: (c.match(/;\s*SameSite=(\w+)/i) || [])[1] || 'not set',
    };
  });
};

const extractForms = (body, pageUrl) => {
  const forms = [];
  const formRe = /<form\b([^>]*)>([\s\S]*?)<\/form>/gi;
  let fm;
  while ((fm = formRe.exec(body)) !== null) {
    const attrs = fm[1];
    const action = (attrs.match(/action=["']([^"']*)["']/i) || [])[1] || pageUrl;
    const method = ((attrs.match(/method=["']([^"']*)["']/i) || [])[1] || 'GET').toUpperCase();
    const inputs = [];
    const inputRe = /<input\b[^>]*name=["']([^"']+)["'][^>]*>/gi;
    let im;
    while ((im = inputRe.exec(fm[2])) !== null) inputs.push(im[1]);
    if (inputs.length) forms.push({ page: pageUrl, action, method, fields: inputs });
  }
  return forms;
};

const headers = homepage.headers || {};
const homepageBody = typeof homepage.body === 'string' ? homepage.body : '';
const securityHeaders = auditHeaders(headers);
const cookies = auditCookies(headers);
let forms = extractForms(homepageBody, startUrl);

// --- JS/CSS asset discovery + bundle analysis ---
// Modern SPAs (Angular/React/Vue) don't expose their real attack surface via
// server-rendered HTML - the actual routes and REST/API paths only exist as
// strings inside the compiled JS bundle. A static path wordlist alone will
// never find these. Fetch the referenced JS assets and pull real path
// fragments out of them instead of guessing.
const assetRe = /(?:src|href)=["']([^"']+\.(?:js|css))["']/gi;
const assetPaths = new Set();
let am;
while ((am = assetRe.exec(homepageBody)) !== null) assetPaths.add(am[1]);
const jsAssetUrls = Array.from(assetPaths)
  .filter((a) => a.endsWith('.js'))
  .map((a) => resolveHref(a, startUrl, origin))
  .filter((u) => u.startsWith(origin));

let bundleEvidence = [], discoveredApiPaths = [];
for (const assetUrl of jsAssetUrls.slice(0, 6)) {
  const res = await fetchUrl(assetUrl);
  if (!res || typeof res.body !== 'string') continue;
  const body = res.body;
  const pathRe = /\/(?:rest|api)\/[a-zA-Z0-9_\-\/]+/g;
  const hits = new Set();
  let pm;
  while ((pm = pathRe.exec(body)) !== null) hits.add(pm[0].replace(/\/$/, ''));
  for (const h of hits) discoveredApiPaths.push(h);
  const generator = body.match(/<meta\s+name=["']generator["']\s+content=["']([^"']+)["']/i);
  if (generator) bundleEvidence.push(`meta generator tag: "${generator[1]}"`);
}
discoveredApiPaths = Array.from(new Set(discoveredApiPaths)).slice(0, 40);

const comments = homepageBody.match(/<!--[\s\S]{0,200}?-->/g) || [];
for (const c of comments.slice(0, 5)) {
  const text = c.replace(/<!--|-->/g, '').trim();
  if (text) bundleEvidence.push(`HTML comment: "${text.slice(0, 150)}"`);
}
for (const a of Array.from(assetPaths).slice(0, 30)) bundleEvidence.push(`asset reference: ${a}`);
const fingerprint = {
  assetCount: assetPaths.size,
  evidenceStrings: bundleEvidence,
  jsAssetUrls,
};

// --- Baselined content discovery: static wordlist + real endpoints pulled
// from the JS bundle, so discovery isn't limited to guessed common paths. ---
const COMMON_PATHS = [
  '/robots.txt', '/sitemap.xml', '/.well-known/security.txt', '/.git/HEAD',
  '/.env', '/admin', '/api', '/graphql', '/swagger.json', '/swagger-ui.html',
  '/package.json', '/server-status', '/.htaccess', '/actuator/health', '/login',
];
const probePaths = Array.from(new Set([...COMMON_PATHS, ...discoveredApiPaths]));

const simpleHash = (s) => { let h = 0; for (let i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) | 0; } return h; };
const baselinePath = `/__recon_baseline_${Date.now()}_${Math.floor(Math.random() * 1e6)}__`;
const baselineRes = await fetchUrl(`${origin}${baselinePath}`);
const baseline = baselineRes ? {
  status: baselineRes.statusCode,
  length: (typeof baselineRes.body === 'string' ? baselineRes.body.length : 0),
  hash: simpleHash(typeof baselineRes.body === 'string' ? baselineRes.body : ''),
} : null;

const pathResults = [];
for (const p of probePaths) {
  const res = await fetchUrl(`${origin}${p}`);
  if (!res) continue;
  const body = typeof res.body === 'string' ? res.body : '';
  const signature = { status: res.statusCode, length: body.length, hash: simpleHash(body) };
  const matchesBaseline = baseline && signature.status === baseline.status &&
    signature.length === baseline.length && signature.hash === baseline.hash;
  pathResults.push({
    path: p,
    status: res.statusCode,
    distinctFromBaseline: !matchesBaseline,
    fromJsBundle: discoveredApiPaths.includes(p),
  });
}

const queue = [{ url: startUrl, depth: 1 }];
const pages = [];
while (queue.length && pages.length < maxPages) {
  const { url, depth } = queue.shift();
  if (visited.has(url)) continue;
  visited.add(url);
  const res = await fetchUrl(url);
  if (!res) continue;
  const body = typeof res.body === 'string' ? res.body : '';
  const titleMatch = body.match(/<title[^>]*>([^<]*)<\/title>/i);
  pages.push({ url, status: res.statusCode, title: titleMatch ? titleMatch[1].trim() : null });
  if (url !== startUrl) forms = forms.concat(extractForms(body, url));
  if (depth < maxDepth) {
    const hrefRe = /href=["']([^"'#]+)["']/gi;
    let hm;
    while ((hm = hrefRe.exec(body)) !== null) {
      try {
        const abs = resolveHref(hm[1], url, origin);
        if (abs.startsWith(origin) && !visited.has(abs) && (queue.length + pages.length) < maxPages) {
          queue.push({ url: abs, depth: depth + 1 });
        }
      } catch (e) {}
    }
  }
}
let robotsStatus = null, sitemapStatus = null;
const robotsRes = pathResults.find((r) => r.path === '/robots.txt');
if (robotsRes) robotsStatus = robotsRes.status;
const sitemapRes = pathResults.find((r) => r.path === '/sitemap.xml');
if (sitemapRes) sitemapStatus = sitemapRes.status;

const coverage = [...ctx.attckCoverage, { technique: 'T1594', name: 'Search Victim-Owned Websites', status: 'executed' }];
return [{ json: { ...ctx, attckCoverage: coverage, webScan: {
  skipped: false, reachable: true, origin,
  headers,
  securityHeaders,
  cookies,
  fingerprint,
  discoveredApiPaths,
  forms,
  contentDiscovery: pathResults,
  robotsTxtStatus: robotsStatus, sitemapXmlStatus: sitemapStatus,
  pagesCrawled: pages.length, pages
} } }];

const data = $json;
const now = new Date();
const pad = n => String(n).padStart(2, '0');
const ts = `${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;

return [{ json: { ...data, reportTimestamp: ts, reportFilename: `${data.target}-${ts}.md` } }];

const ctx = $('Build Deterministic Report Sections').item.json;
const section6Text = $('Aggregate Section 6').item.json.section6Text || '## 6. If I Were Attacking This\n\n(Not generated.)';

// Section 7 extraction. Two real bugs found and fixed here via raw
// execution data, not by guessing:
// 1. qwen3 sometimes mentions the required <ANSWER>/</ANSWER> tag names
//    inside its own reasoning prose (e.g. "Check that the answer is
//    wrapped in <ANSWER> and </ANSWER> without any extra text.") before
//    ever producing the real answer. A first-match regex pairs that
//    self-reminder's tags together and captures nothing (or near-nothing)
//    real, discarding the genuinely well-formed answer that follows.
//    Fixed by taking the LAST <ANSWER>/</ANSWER> pair, not the first, and
//    requiring a minimum length so a short spurious match still falls
//    through to the next path rather than being trusted.
// 2. qwen3 doesn't always emit <ANSWER> tags at all even when it produces
//    a correct, well-scoped answer - falls back to finding the last
//    occurrence of the exact required heading, but only if that tail
//    contains none of the first-person hedging language real leaked
//    reasoning always has, so raw chain-of-thought still never leaks
//    through if neither path finds a clean answer.
let raw = $json.text || $json.output || '';
raw = raw.replace(/^[\s\S]*?<\/think>\s*/i, '');

let section7Text = '';
const lastOpen = raw.lastIndexOf('<ANSWER>');
const lastClose = raw.lastIndexOf('</ANSWER>');
if (lastOpen !== -1 && lastClose !== -1 && lastClose > lastOpen) {
  const candidate = raw.slice(lastOpen + '<ANSWER>'.length, lastClose).trim();
  if (candidate.length > 20) section7Text = candidate;
}

if (!section7Text) {
  const heading = '## 7. ATT&CK-Aligned Next-Phase Plan';
  const lastIdx = raw.lastIndexOf(heading);
  if (lastIdx !== -1) {
    const tail = raw.slice(lastIdx).trim();
    const looksLikeReasoning = /\b(wait|let me|i need to|i think|maybe|perhaps|the user (wants|said|mentioned))\b/i.test(tail);
    if (!looksLikeReasoning) section7Text = tail;
  }
}

if (!section7Text) {
  section7Text = '## 7. ATT&CK-Aligned Next-Phase Plan\n\n(Ollama did not return a well-formed answer for this section - raw reasoning discarded rather than included.)';
} else if (!/^#{1,3}\s/.test(section7Text)) {
  section7Text = '## 7. ATT&CK-Aligned Next-Phase Plan\n\n' + section7Text;
}

const header = `# Recon Report: ${ctx.target}\n\n- Timestamp: ${ctx.reportTimestamp}\n- Scan intensity: ${ctx.scanIntensity}\n\n---\n\n`;
const reportContent = header + ctx.sections1to5 + '\n' + section6Text + '\n\n' + section7Text + '\n\n' + ctx.section8 + '\n';
return [{ json: { ...ctx, reportContent } }];

const ctx = $json;
const jsUrls = (ctx.webScan && ctx.webScan.fingerprint && ctx.webScan.fingerprint.jsAssetUrls) || [];
if (jsUrls.length === 0) {
  return [{ json: { ...ctx, command: 'echo \'{"data":[]}\'' } }];
}
const dlCmds = jsUrls.map((u, i) => `curl -s -m 15 -o /tmp/retire-assets/asset${i}.js "${u}"`).join(' && ');
const command = `mkdir -p /tmp/retire-assets && rm -f /tmp/retire-assets/* && ${dlCmds} && retire --path /tmp/retire-assets --outputformat json --exitwith 0 2>/dev/null || echo '{"data":[]}'`;
return [{ json: { ...ctx, command } }];

const ctx = $('Build Component Scan Command').item.json;
let componentFindings = [];
try {
  const out = JSON.parse($json.stdout || '{"data":[]}');
  for (const file of (out.data || [])) {
    for (const res of (file.results || [])) {
      for (const vuln of (res.vulnerabilities || [])) {
        componentFindings.push({
          component: res.component,
          version: res.version,
          severity: vuln.severity || 'unknown',
          summary: (vuln.identifiers && vuln.identifiers.summary) || null,
          cve: (vuln.identifiers && vuln.identifiers.CVE) || [],
          info: vuln.info || [],
        });
      }
    }
  }
} catch (e) { componentFindings = []; }
return [{ json: { ...ctx, componentFindings } }];

const ctx = $json;
const lines = [];
const p = (s='') => lines.push(s);

// --- Deterministic CVE dedup (moved to the top so both the executive
// summary below and the Section 5 CVE table further down share one
// computation instead of two). vulners cites the same underlying
// vulnerability from many sources (packetstorm/metasploit/exploitdb/
// githubexploit/zdt/etc, each its own entry at the same CVSS) - only
// entries whose id is an actual CVE number are distinct, uniquely-
// identified vulnerabilities; everything else is a citation of public
// exploit tooling *for* one of those CVEs, not a separate finding. Bucket
// by port+product+version, dedupe real CVEs by their own id (never by CVSS
// alone - two different CVEs can share a score). vulners does NOT map an
// exploit-tooling citation to a specific CVE id, so "which CVE does this
// exploit target" is not directly determinable from this data source -
// matching by exact CVSS score within the same bucket is the closest
// available correlation, not a guaranteed per-CVE mapping. Verified live
// against a real multi-CVE target (Apache httpd 2.2.8, 100+ distinct
// catalogued CVEs) before shipping.
const cveHits = [];
if (ctx.portScan && !ctx.portScan.skipped) {
  for (const o of ctx.portScan.openPorts) {
    for (const s of (o.scripts || [])) {
      if (s.id === 'vulners' && s.cves) {
        for (const c of s.cves) cveHits.push({ port: o.port, service: o.service, product: o.product, version: o.version, ...c });
      }
    }
  }
}
const isRealCve = (id) => /^CVE-\d{4}-\d+$/.test(id || '');
// Same reconciliation as Extract Findings List (Section 6) - a ZAP SQLi
// alert that sqlmap already directly tested (same endpoint/parameter) and
// found negative on should not drive the executive summary or be displayed
// as an unqualified confirmed finding in Section 5.
const sameEndpoint = (urlA, urlB) => {
  try {
    const a = new URL(urlA), b = new URL(urlB);
    return a.origin === b.origin && a.pathname === b.pathname;
  } catch (e) { return false; }
};
const sqlmapTestedNegative = (url) => {
  if (!ctx.sqlmapScan || ctx.sqlmapScan.skipped) return false;
  // Per-endpoint, not gated on the global .vulnerable flag - now that
  // sqlmap tests up to 10 candidates, one of them can be genuinely
  // vulnerable while a different one (the one a ZAP alert points at) is
  // negative, and the reconciliation needs to match on that specific
  // endpoint, not silently skip because *something else* was vulnerable.
  return (ctx.sqlmapScan.results || []).some(r => !r.vulnerable && sameEndpoint(r.url, url));
};
const buckets = new Map();
for (const c of cveHits) {
  const key = `${c.port}|${c.product}|${c.version}`;
  if (!buckets.has(key)) buckets.set(key, { port: c.port, service: c.service, product: c.product, version: c.version, cves: new Map(), exploitCvss: new Set() });
  const b = buckets.get(key);
  if (c.isExploit) b.exploitCvss.add(c.cvss);
  if (isRealCve(c.id)) {
    const existing = b.cves.get(c.id);
    if (!existing || c.cvss > existing.cvss) b.cves.set(c.id, { id: c.id, cvss: c.cvss });
  }
}
const exploitable = [];
const researchOnly = [];
for (const b of buckets.values()) {
  for (const cve of b.cves.values()) {
    const row = { port: b.port, service: b.service, product: b.product, version: b.version, id: cve.id, cvss: cve.cvss };
    if (b.exploitCvss.has(cve.cvss)) exploitable.push(row); else researchOnly.push(row);
  }
}
exploitable.sort((a, b) => (b.cvss || 0) - (a.cvss || 0));
researchOnly.sort((a, b) => (b.cvss || 0) - (a.cvss || 0));
const dedupedCves = [
  ...exploitable.map(c => ({ ...c, exploitable: true })),
  ...researchOnly.map(c => ({ ...c, exploitable: false })),
];

// --- Deterministic Executive Risk Summary - no LLM. Severity/count is a
// pure code operation (max + tie detection), and asking a local model to do
// this was producing real bugs: an arbitrary low-severity finding named as
// "most serious" while real CVSS-10s sat in the same report, and later, one
// arbitrary CVSS-10 named out of several tied at the top with no stated
// tie-break rule. Also surfaces total confirmed-finding count, which is
// itself a signal worth stating, not just naming one winner. ---
// Each finding gets a numeric score (CVE: its real CVSS float; everything
// else: a fixed-point estimate) so the tie-break below can match on the
// TRUE maximum value, not a coarse word bucket - the first version of this
// bucketed by severity word (critical/high/medium/low), and on a target
// like this with dozens of CVEs clustered in the 9.0-10.0 CVSS range, every
// one of them mapped to "critical" and got listed as "tied," producing a
// useless 29-line executive summary. Matching the exact score instead
// surfaces only genuine ties (e.g. three real CVSS-10s), with the rest
// folded into the severity-band counts.
const riskWordForScore = (score) => score >= 9 ? 'critical' : score >= 7 ? 'high' : score >= 4 ? 'medium' : 'low';
const summaryFindings = [];
for (const c of dedupedCves) {
  summaryFindings.push({ label: `${c.product || 'unknown'} ${c.version || ''} (port ${c.port}, ${c.id})`.replace(/\s+/g, ' ').trim(), score: c.cvss || 0 });
}
const componentSevScore = { critical: 10, high: 8, medium: 5, low: 2 };
for (const c of (ctx.componentFindings || [])) {
  summaryFindings.push({ label: `${c.component} ${c.version} (vulnerable component${c.cve && c.cve.length ? ', ' + c.cve.join(', ') : ''})`, score: componentSevScore[(c.severity || 'medium').toLowerCase()] || 5 });
}
for (const r of ((ctx.sqlmapScan && ctx.sqlmapScan.results) || [])) {
  if (r.vulnerable) summaryFindings.push({ label: `Confirmed SQL injection (sqlmap): ${r.url}`, score: 10 });
}
if (ctx.zapScan && !ctx.zapScan.skipped && ctx.zapScan.reachable) {
  const zapByName = new Map();
  for (const a of (ctx.zapScan.alerts || [])) {
    const g = zapByName.get(a.name) || { risk: a.risk, urls: [] };
    g.urls.push(a.url);
    zapByName.set(a.name, g);
  }
  for (const [name, info] of zapByName) {
    const contradicted = /sql injection/i.test(name) && info.urls.some(u => sqlmapTestedNegative(u));
    if (contradicted) continue;
    summaryFindings.push({ label: `ZAP alert: ${name}`, score: componentSevScore[(info.risk || 'medium').toLowerCase()] || 5 });
  }
}
for (const f of (ctx.sensitiveFileExposures || [])) {
  if (f.confirmed) summaryFindings.push({ label: `Exposed sensitive file: ${f.path}`, score: 8 });
}

// GraphQL exposure counts as a confirmed finding.
if (ctx.graphql && ctx.graphql.detected) {
  if (ctx.graphql.introspectionEnabled) summaryFindings.push({ label: `GraphQL introspection enabled: ${ctx.graphql.endpoint}`, score: 5 });
  else if (ctx.graphql.suggestionLeak) summaryFindings.push({ label: `GraphQL schema leak via field suggestions: ${ctx.graphql.endpoint}`, score: 4 });
}
// nuclei findings (exposures / misconfig / default-logins) count as confirmed
// - a template fired against a live response, not a version guess.
for (const f of ((ctx.nucleiScan && ctx.nucleiScan.findings) || [])) {
  if (['info', 'unknown'].includes(f.severity)) continue;
  summaryFindings.push({ label: `Nuclei: ${f.name}${f.matchedAt ? ' at ' + f.matchedAt : ''}`, score: f.cvss || componentSevScore[f.severity] || 3 });
}
// WordPress: exploit-backed core CVEs (NVD CPE match) + XML-RPC exposure.
if (ctx.wpscanScan && ctx.wpscanScan.ran) {
  const wpv = ctx.wpscanScan.coreVersion || 'core';
  for (const v of (ctx.wpscanScan.coreVulns || [])) {
    if (!v.hasExploit) continue;
    summaryFindings.push({ label: `WordPress ${wpv} ${v.cve || v.title}`, score: v.cvss || 8 });
  }
  if (ctx.wpscanScan.xmlrpcEnabled) summaryFindings.push({ label: 'WordPress XML-RPC enabled (pingback SSRF vector)', score: 5 });
}
const totalConfirmed = summaryFindings.length;
let escalationRecommendation;
if (!totalConfirmed) {
  escalationRecommendation = 'No confirmed findings within what was tested.';
} else {
  const bandCounts = { critical: 0, high: 0, medium: 0, low: 0 };
  for (const f of summaryFindings) bandCounts[riskWordForScore(f.score)]++;
  const bandSummary = Object.entries(bandCounts).filter(([, n]) => n > 0).map(([w, n]) => `${n} ${w}`).join(', ');
  const maxScore = Math.max(...summaryFindings.map(f => f.score));
  const maxWord = riskWordForScore(maxScore);
  const topFindings = summaryFindings.filter(f => f.score === maxScore);
  const tieNote = topFindings.length > 1
    ? `${topFindings.length} confirmed findings tied at the highest severity (${maxWord}, score ${maxScore}): ${topFindings.map(f => f.label).join('; ')}`
    : `The most serious confirmed finding is ${topFindings[0].label} (${maxWord}, score ${maxScore})`;
  escalationRecommendation = `${tieNote}. ${totalConfirmed} confirmed finding(s) total this run (${bandSummary}). Overall risk level: ${maxWord}.`;
}

