(ctx.tlsScan && !ctx.tlsScan.skipped ? covRan : covNotRun).push('TLS/certificate analysis');
(ctx.attribution ? covRan : covNotRun).push('cloud/network attribution');
(ctx.webScan && ctx.webScan.reachable ? covRan : covNotRun).push('web crawl/content discovery');
(ctx.webScan && ctx.webScan.ajaxSpiderRan ? covRan : covNotRun).push('AJAX-spider endpoint discovery');
(ctx.sqlmapScan && !ctx.sqlmapScan.skipped ? covRan : covNotRun).push('SQL injection testing (sqlmap)');
