else if (ctx.nucleiScan && ctx.nucleiScan.reason && !/toggle off/.test(ctx.nucleiScan.reason)) covNotRun.push('templated scan (nuclei)');
let covLine = `_Scan coverage: ${covRan.length ? covRan.join(', ') : 'DNS/subdomain enumeration only'} run.`;
