    for (const v of (wp.mainTheme.vulns || [])) p(`  - **${v.title}**${v.fixedIn ? ' (fixed in ' + v.fixedIn + ')' : ''}`);
  }
  p(`- Plugins detected (passive): ${wp.plugins && wp.plugins.length ? wp.plugins.map(pl => '\`' + pl.slug + '\`' + (pl.version ? ' ' + pl.version : '')).join(', ') : 'none found'}.`);
  for (const pl of (wp.plugins || [])) {
    for (const v of (pl.vulns || [])) p(`  - \`${pl.slug}\`: **${v.title}**${v.fixedIn ? ' (fixed in ' + v.fixedIn + ')' : ''}${v.refs && v.refs.length ? ' - ' + v.refs.join(', ') : ''}`);
  }
  if (wp.users && wp.users.length) p(`- Users enumerated: ${wp.users.map(u => '\`' + u + '\`').join(', ')}.`);
  const wpExp = [];
  if (wp.xmlrpcEnabled) wpExp.push('XML-RPC enabled (\`/xmlrpc.php\`) - pingback SSRF and \`system.multicall\` credential-bruteforce amplification vector');
  if (wp.readmeExposed) wpExp.push('\`/readme.html\` accessible (version disclosure)');
  if (wp.uploadDirListing) wpExp.push('\`wp-content/uploads/\` directory listing enabled');
  for (const b of (wp.configBackups || [])) wpExp.push('config backup exposed: ' + b);
  for (const e of (wp.dbExports || [])) wpExp.push('database export exposed: ' + e);
  if (wpExp.length) { p('- Exposures:'); for (const e of wpExp) p(`  - ${e}`); }
  const wpOutdated = [].concat(
    (wp.mainTheme && wp.mainTheme.outdated && !((wp.mainTheme.vulns || []).length)) ? ['theme ' + wp.mainTheme.slug + ' ' + (wp.mainTheme.version || '')] : [],
    (wp.plugins || []).filter(pl => pl.outdated && !((pl.vulns || []).length)).map(pl => 'plugin ' + pl.slug + ' ' + (pl.version || '')),
  );
  if (wpOutdated.length) p(`- Outdated (no NVD name match, check exploit-db): ${wpOutdated.join(', ')}.`);
}
p('');

p('### Nuclei (exposures / misconfiguration / default credentials)');
const nu = ctx.nucleiScan;
if (!nu || nu.skipped) {
  p(`- Not run (${nu ? nu.reason : 'toggle off or web target unreachable'}).`);
} else if (!nu.ran) {
  p('- nuclei did not complete.');
} else if (!(nu.findings || []).length) {
  p('- nuclei ran (exposure/misconfiguration/panel/default-credential templates) against the origin; no matches at low severity or above. CVE coverage is handled by nmap-vulners and the WordPress NVD lookup, not this pass.');
} else {
  const bySev = {};
  for (const f of nu.findings) (bySev[f.severity] = bySev[f.severity] || []).push(f);
  for (const sev of ['critical', 'high', 'medium', 'low']) {
    if (!bySev[sev]) continue;
    p(`- **${sev.toUpperCase()}** (${bySev[sev].length}):`);
    for (const f of bySev[sev].slice(0, 25)) p(`  - ${f.name}${f.cve ? ' [' + f.cve + ']' : ''} - \`${f.templateId}\` at ${f.matchedAt}`);
    if (bySev[sev].length > 25) p(`  - ...and ${bySev[sev].length - 25} more`);
  }
}
p('');

p('### GraphQL API');
const gq = ctx.graphql;
if (!gq || gq.detected === false) {
  p(`- No GraphQL endpoint found at the common paths${gq && gq.reason ? ' (' + gq.reason + ')' : ''}.`);
} else {
  p(`- Endpoint: \`${gq.endpoint}\``);
  p(`- Introspection: ${gq.introspectionEnabled ? '**enabled** - full schema readable unauthenticated' + (gq.typeCount ? ` (${gq.typeCount} types${gq.hasMutations ? ', mutations present' : ''})` : '') : (gq.suggestionLeak ? 'disabled, but **field-suggestion hints leak schema names**' : 'disabled, no suggestion leak observed')}`);
  if (gq.getQueriesAllowed) p('- Accepts queries over **GET** (CSRF surface if mutations also run over GET)');
  if (gq.batchingEnabled) p('- **Query batching enabled** (array-batched queries execute in one request - rate-limit / brute-force amplification)');
  for (const ev of (gq.evidence || [])) p(`  - ${ev}`);
}
p('');

p('## 8. Testing Coverage & Gaps');
p('');
p('| Category | Tested this scan? |');
p('|---|---|');
p(`| DNS/WHOIS/Subdomain enumeration | Yes |`);
p(`| Port scanning | ${ctx.portScan && !ctx.portScan.skipped ? 'Yes' : 'No - scanIntensity below dns+ports'} |`);
p(`| Security headers / cookie flags | ${ctx.webScan && ctx.webScan.reachable ? 'Yes' : 'No - web target unreachable/not scanned'} |`);
p(`| Content discovery (baselined) | ${ctx.webScan && ctx.webScan.reachable ? 'Yes' : 'No'} |`);
p(`| Vulnerable components (retire.js) | ${ctx.componentFindings !== undefined ? 'Yes' : 'No'} |`);
p(`| Known CVE matches (nmap vulners) | ${ctx.portScan && !ctx.portScan.skipped ? 'Yes' : 'No - port scan not run'} |`);
p(`| TLS/certificate analysis (testssl.sh) | ${ctx.tlsScan && !ctx.tlsScan.skipped ? 'Yes' : 'No - port 443 not open or port scan not run'} |`);
p(`| Cloud/network attribution (ASN, CNAME chain) | ${ctx.attribution ? 'Yes' : 'No'} |`);
p(`| SQL/NoSQL injection (sqlmap) | ${ctx.sqlmapScan && !ctx.sqlmapScan.skipped ? 'Yes' : 'No - toggle off or web unreachable'} |`);
p(`| XSS / broader web vuln scan (ZAP) | ${ctx.zapScan && !ctx.zapScan.skipped && ctx.zapScan.reachable ? 'Yes' : 'No - toggle off, ZAP not running, or web unreachable'} |`);
p(`| WordPress-specific scan (wpscan) | ${ctx.wpscanScan && ctx.wpscanScan.ran ? 'Yes' : (ctx.wpscanScan && ctx.wpscanScan.skipped ? 'No - ' + ctx.wpscanScan.reason : 'No - not WordPress or toggle off')} |`);
p(`| Templated scan (nuclei) | ${ctx.nucleiScan && ctx.nucleiScan.ran ? 'Yes' : (ctx.nucleiScan && ctx.nucleiScan.skipped ? 'No - ' + ctx.nucleiScan.reason : 'No')} |`);
p(`| GraphQL API testing | ${ctx.graphql ? (ctx.graphql.detected ? 'Yes' : 'No GraphQL endpoint found') : 'No - web target unreachable'} |`);
p(`| AJAX-spider endpoint discovery (real browser, SPA-aware) | ${ctx.webScan && ctx.webScan.ajaxSpiderRan ? 'Yes' : 'No - web target unreachable or scan not run'} |`);
p(`| Broken Authentication (rate-limiting, JWT weaknesses, password reset flaws) | No - requires active authenticated testing not performed by this scan |`);
p(`| Broken Access Control / IDOR | No - requires authenticated, session-aware testing |`);
p(`| Broken Anti-Automation | No - requires repeated-request active testing |`);
p(`| Cryptographic Issues (TLS/cipher grade) | No - not implemented in this scan |`);
p(`| XML External Entities (XXE) | No - requires crafted payloads to file-upload endpoints |`);
p(`| Insecure Deserialization | No - requires crafted payload testing |`);
p(`| Insufficient Logging & Monitoring | Not detectable from external recon - requires server-side log access |`);
p('');

const fullText = lines.join('\n');
const splitIdx = fullText.indexOf('## 8. Testing Coverage & Gaps');
const sections1to5 = splitIdx >= 0 ? fullText.slice(0, splitIdx) : fullText;
const section8 = splitIdx >= 0 ? fullText.slice(splitIdx) : '';

return [{ json: { ...ctx, sections1to5, section8, dedupedCves } }];

const ctx = $json;
const ws = ctx.webScan;
if (!ws || !ws.reachable) { return [{ json: ctx }]; }
const zapBase = 'http://zap:8090';
const targetUrl = ws.origin + '/';
const call = async (path) => {
  try {
    return await this.helpers.httpRequest({ method: 'GET', url: `${zapBase}${path}`, timeout: 10000, json: true });
  } catch (e) { return null; }
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const started = await call(`/JSON/ajaxSpider/action/scan/?url=${encodeURIComponent(targetUrl)}`);
let status = 'stopped';
if (started && started.Result === 'OK') {
  status = 'running';
  let polls = 0;
  while (status !== 'stopped' && polls < 20) {
    await sleep(5000);
    const s = await call('/JSON/ajaxSpider/view/status/');
    status = s ? s.status : 'stopped';
    polls++;
  }
}

const resultsRes = await call('/JSON/ajaxSpider/view/results/?start=0&count=500');
const raw = (resultsRes && resultsRes.results) || [];

// Real-time/protocol paths (Socket.IO, webpack HMR, etc.) generate many
// near-duplicate requests differing only by a volatile handshake token
// (t=/sid=) - collapse those into one representative entry per path instead
// of flooding the report with dozens of "distinct" findings that are really
// the same one fact ("this app uses Socket.IO").
const infraPathRe = /\/(socket\.io|sockjs-node|__webpack_hmr|hot-update)\//i;
const infraParamRe = /^(EIO|transport|sid|t|callback|jsonp)$/i;
function normalizeForDedup(url) {
  const [base, qs] = url.split('?');
  if (!infraPathRe.test(base) || !qs) return url;
  const kept = qs.split('&').filter(p => !infraParamRe.test(p.split('=')[0]));
  return kept.length ? base + '?' + kept.join('&') : base;
}

const seen = new Set();
const discovered = [];
for (const r of raw) {
  const line = (r.requestHeader || '').split('\r\n')[0] || '';
  const m = line.match(/^(GET|POST|PUT|DELETE)\s+(\S+)/);
  if (!m) continue;
  const method = m[1];
  const url = m[2];
  if (!url.startsWith(ws.origin)) continue;
  const dedupKey = method + ' ' + normalizeForDedup(url);
  if (seen.has(dedupKey)) continue;
  seen.add(dedupKey);
  discovered.push({ method, url, body: r.requestBody || '' });
}

const existingPaths = new Set((ws.contentDiscovery || []).map(p => p.path));
const newContentEntries = [];
for (const d of discovered) {
  const path = d.url.slice(ws.origin.length) || '/';
  const bareePath = path.split('?')[0];
  if (existingPaths.has(bareePath) || existingPaths.has(path)) continue;
  existingPaths.add(path);
  newContentEntries.push({ path, status: 'observed', distinctFromBaseline: true, fromAjaxSpider: true });
}

const parameterizedRequests = discovered.filter(d => {
  const qIdx = d.url.indexOf('?');
  const hasQuery = qIdx >= 0 && d.url.length > qIdx + 1;
  return hasQuery || (d.method === 'POST' && d.body);
});

return [{ json: { ...ctx, webScan: {
  ...ws,
  contentDiscovery: [...(ws.contentDiscovery || []), ...newContentEntries],
  ajaxSpiderRan: true,
  ajaxSpiderUrlsObserved: discovered.length,
  ajaxParameterizedRequests: parameterizedRequests,
} } }];

const ctx = $json;
const ws = ctx.webScan;
if (!ws || !ws.reachable) { return [{ json: ctx }]; }

// A file being merely 200-reachable isn't itself the finding - what matters
// is whether the path LOOKS like a leftover backup/config/source-control
// artifact that should never be web-served. This pattern is generic across
// any target (any web stack can leak a .bak/.env/.git file), not tuned to
// any one app.
const sensitiveRe = /\.(bak|old|orig|swp|sql|log|env|ya?ml|zip|tar|gz|json\.bak|config)(\.[a-z0-9]+)?$/i;
const gitRe = /\/\.git\//i;

const candidates = new Map(); // url -> {path, source}
for (const c of (ws.contentDiscovery || [])) {
  if (!c.distinctFromBaseline) continue;
  if (sensitiveRe.test(c.path) || gitRe.test(c.path)) {
    const url = ws.origin + c.path;
    if (!candidates.has(url)) candidates.set(url, { path: c.path, source: 'content discovery', status: c.status });
  }
}
if (ctx.zapScan && ctx.zapScan.alerts) {
  for (const a of ctx.zapScan.alerts) {
    if (!a.url || !a.url.startsWith(ws.origin)) continue;
    const path = a.url.slice(ws.origin.length).split('?')[0];
    if (sensitiveRe.test(path) || gitRe.test(path)) {
      if (!candidates.has(a.url)) candidates.set(a.url, { path, source: 'ZAP alert', status: null });
    }
  }
}

const excerpts = [];
let fetched = 0;
for (const [url, meta] of candidates) {
  if (fetched >= 5) break;
  fetched++;
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url, timeout: 8000, returnFullResponse: true });
    const status = res.statusCode;
    const body = typeof res.body === 'string' ? res.body : JSON.stringify(res.body);
    if (status === 200 && body && body.length > 0) {
      excerpts.push({ url, path: meta.path, source: meta.source, status, confirmed: true, excerpt: body.slice(0, 1000), length: body.length });
    } else {
      // Flagged by ZAP/content-discovery but not live-confirmed on our own
      // re-fetch (blocked, transient, or the original alert didn't imply
      // 200 content access) - surface it honestly rather than silently
      // dropping a real signal, the same mistake fixed earlier for ftp-anon.
      excerpts.push({ url, path: meta.path, source: meta.source, status, confirmed: false });
    }
  } catch (e) {
    excerpts.push({ url, path: meta.path, source: meta.source, status: 'fetch failed', confirmed: false });
  }
}

return [{ json: { ...ctx, sensitiveFileExposures: excerpts } }];

const ctx = $json;
const findings = [];

// Reconciliation helper: a ZAP active-scan alert is a heuristic, not a
// confirmed exploit - if sqlmap already directly tested the exact same
// endpoint/parameter and came back negative, that real test outranks ZAP's
// heuristic and the alert should not be treated as an equally "confirmed"
// finding (this was producing a genuinely contradictory report: the
// executive summary naming a ZAP SQLi alert as the most serious confirmed
// finding while the SQL Injection Testing section, a few paragraphs later,
// said sqlmap tested that exact same endpoint and found nothing).
const sameEndpoint = (urlA, urlB) => {
  try {
    const a = new URL(urlA), b = new URL(urlB);
    return a.origin === b.origin && a.pathname === b.pathname;
  } catch (e) { return false; }
};
const sqlmapTestedNegative = (url) => {
  if (!ctx.sqlmapScan || ctx.sqlmapScan.skipped || ctx.sqlmapScan.vulnerable) return false;
  return (ctx.sqlmapScan.targetsUsed || []).some(t => sameEndpoint(t, url));
};

// Deterministic finding -> tool dispatch. This is the fix for the original
// Kali-VM finding (curl/nikto overfit onto everything regardless of fit):
// every finding category gets an explicit, code-decided {tool, command,
// rationale, verification} here, keyed on the finding's actual structured
// attributes (confirmed vs unconfirmed, exploit availability from the
// already-deduped CVE data), not a flat tool list handed to the LLM to pick
// from. `verification` is also decided per category, not per finding
// instance - the check for "did the Metasploit search for CVE-X work" is
// structurally identical for every CVE in this category, only the CVE id
// changes, so there is no per-finding judgment left to make at all (this is
// also why Section 6 no longer calls an LLM - see Build Deterministic Bullet).
const dispatch = (category, opts = {}) => {
  switch (category) {
    case 'Missing Security Headers':
      return { tool: 'None (informational)', command: null, rationale: 'Defense-in-depth gap, not independently exploitable on its own - note for remediation, no active tool applies.', verification: null };
    case 'Content Discovery':
      return { tool: 'gobuster/ffuf (deeper enumeration)', command: `gobuster dir -u ${opts.origin} -w /opt/wordlists/common.txt -x php,asp,aspx,jsp,json`, rationale: 'Real directory/API surface already found - the next step is widening enumeration depth against a real target, not guessing at an exploit blind.', verification: 'gobuster reports additional 2xx/3xx paths beyond what the baseline wordlist run already found.' };
    case 'Exposed Sensitive File - confirmed':
      return { tool: 'Manual review', command: 'Read the fetched excerpt already captured above', rationale: 'Content is already fetched and confirmed exposed - read it directly for credentials/connection strings, no further tooling needed.', verification: null };
    case 'Exposed Sensitive File - unconfirmed':
      return { tool: 'curl (confirmation only)', command: `curl -i '${opts.url}'`, rationale: 'Flagged by discovery but not live-confirmed this run - the only next step is confirming access, not exploitation.', verification: 'HTTP response status is 200 with a non-empty body.' };
    case 'Vulnerable Component':
      return { tool: 'searchsploit', command: `searchsploit ${opts.component} ${opts.version}`, rationale: 'Client-side JS library CVE with no exploit-availability signal from this scan - check exploit-db directly rather than assume either way.', verification: 'searchsploit returns at least one matching exploit-db entry for the component/version.' };
    case 'SQL Injection - confirmed':
      return { tool: 'sqlmap (escalate)', command: `sqlmap -u '${opts.surface}' --batch --dump`, rationale: 'Injection is already confirmed - escalate straight to data extraction, no further probing needed.', verification: 'sqlmap reports a non-empty --dump result (table/column names extracted).' };
    case 'SQL Injection - negative':
      return { tool: 'None', command: null, rationale: 'Already tested negative against a real, observed endpoint - no further action from this signal.', verification: null };
    case 'ZAP - sqli':
      return { tool: 'sqlmap', command: `sqlmap -u '${opts.url}' --batch`, rationale: 'ZAP flagged a SQL injection pattern - confirm with sqlmap against the exact flagged URL.', verification: 'sqlmap confirms the injectable parameter (same signal as a direct SQL Injection - confirmed finding).' };
    case 'ZAP - sqli contradicted by sqlmap':
      return { tool: 'None (contradicted by direct testing)', command: null, rationale: 'sqlmap already tested this exact endpoint/parameter directly (see the SQL Injection Testing section) and found no injectable parameter - ZAP\'s active-scan heuristic likely false-positived here, not a confirmed finding.', verification: null };
    case 'ZAP - xss':
      return { tool: 'Manual verification (Burp Repeater)', command: `Replay ${opts.url} with a real XSS payload and confirm reflection/execution`, rationale: 'XSS needs a human/Burp to confirm real reflection or execution context - not something to auto-fire a payload at blind.', verification: 'The payload reflects unescaped in the HTTP response body, or executes in a real browser context.' };
    case 'ZAP - informational':
      return { tool: 'None (informational)', command: null, rationale: 'Header/config-class alert, not independently exploitable - note for remediation, no active tool applies.', verification: null };
    case 'ZAP - false positive':
      return { tool: 'None (false positive)', command: null, rationale: 'Every affected URL is Socket.IO transport handshake traffic, not an application session - do not action.', verification: null };
    case 'ZAP - unmapped':
      return { tool: 'Manual triage', command: null, rationale: 'No deterministic rule defined yet for this ZAP alert type - flag for manual review rather than guess a tool.', verification: null };
    case 'Known CVE - exploitable':
      return { tool: 'Metasploit', command: `msfconsole -q -x "search cve:${opts.id}; exit"`, rationale: `Confirmed CVE (${opts.id}) with a matched public exploit at the same severity - identify and run the applicable Metasploit module directly, not a generic scanner.`, verification: 'msfconsole search output lists at least one matching module for this CVE ID.' };
    case 'Known CVE - research-only':
      return { tool: 'None (research only)', command: null, rationale: `Catalogued CVE (${opts.id}) with no known public exploit today - monitor exploit-db/GitHub advisories for a module landing, no active tool recommended yet.`, verification: null };
    case 'Discovered But Untestable':
      return {
        tool: 'sqlmap (manual follow-up - needs real/test credentials)',
        command: `sqlmap -u '${opts.url}' --data 'email=test&password=test' --batch --level=1 --risk=1`,
        rationale: 'Automated crawling cannot submit this form - no credentials to try, and for a JS-rendered SPA the form is client-side only, not in server-rendered HTML to fill in even if it did. The endpoint is real and discovered; it is specifically the automated test that is missing.',
        verification: 'Run manually with real/test credential values substituted for the placeholders above - sqlmap reports either an injection point or a genuine negative once actually tested.',
      };
    case 'WordPress - vulnerable component':
      return {
        tool: opts.hasExploit ? 'Metasploit' : 'searchsploit',
        command: opts.hasExploit
          ? `msfconsole -q -x "search ${opts.cve ? 'cve:' + opts.cve : (opts.slug === 'wordpress' ? 'wordpress' : 'wordpress ' + opts.slug)}; exit"`
          : (opts.cve
              ? `searchsploit --cve ${opts.cve.replace(/^CVE-/i, '')}   # also: msfconsole -q -x "search cve:${opts.cve}; exit"`
              : `searchsploit wordpress ${opts.slug} ${opts.version}`),
        rationale: opts.hasExploit
          ? 'NVD lists a public exploit reference for this CVE - identify and run the module directly, same as a server-side CVE with a known exploit.'
          : 'NVD CPE match on the core version - catalogued CVE with no linked public exploit; check exploit-db before assuming either way.',
        verification: 'searchsploit or msfconsole returns at least one matching entry/module for this vuln.',
      };
    case 'WordPress - outdated component':
      return {
        tool: 'searchsploit',
        command: `searchsploit ${opts.slug} ${opts.version}`,
        rationale: `wpscan flagged ${opts.slug} ${opts.version} as outdated. Core CVEs are looked up against NVD by CPE; plugin/theme CVE attribution by name is unreliable and was not auto-run, so check exploit-db directly for this ${opts.kind}.`,
        verification: 'searchsploit returns at least one exploit-db entry for this component/version.',
      };
    case 'WordPress - xmlrpc':
      return {
        tool: 'Metasploit (pingback SSRF)',
        command: `msfconsole -q -x "use auxiliary/scanner/http/wordpress_pingback_access; set RHOSTS ${opts.host}; run; exit"`,
        rationale: 'XML-RPC pingback can be driven to make server-side requests to arbitrary hosts (SSRF / internal port discovery). system.multicall additionally amplifies credential attacks - but online password brute-forcing is out of scope for this platform (availability / rules of engagement), so the actionable automated step is the SSRF probe, not the login attack.',
        verification: 'The pingback_access module confirms the endpoint accepts pingback.ping and the server issues an outbound request on command.',
      };
    case 'WordPress - user enum':
      return {
        tool: 'Manual follow-up (credential testing - not automated)',
        command: `wpscan --url ${opts.origin}/ --usernames ${opts.users} --passwords <wordlist> --max-threads 5   # run deliberately, account-lockout risk understood`,
        rationale: 'Valid usernames are the first half of a credential attack, but online password brute-forcing risks account lockout and availability degradation - this platform does not automate it (rules of engagement). Left for a human to run deliberately against a chosen wordlist.',
        verification: 'A human-run credential test reports either a valid login or a clean negative against the chosen wordlist.',
      };
    case 'Nuclei - cve':
      return {
        tool: opts.hasExploit ? 'Metasploit' : 'searchsploit',
        command: `msfconsole -q -x "search cve:${opts.cve}; exit"   # or: searchsploit --cve ${String(opts.cve).replace(/^CVE-/i, '')}`,
        rationale: `nuclei's template for ${opts.cve} fired against ${opts.matchedAt} - this is a positive match, not a version guess. Go straight to the exploit.`,
        verification: 'msfconsole/searchsploit returns a matching module/entry for the CVE.',
      };
    case 'Nuclei - exposure':
      return {
        tool: 'curl (fetch & assess)',
        command: `curl -i '${opts.matchedAt}'`,
        rationale: 'nuclei flagged an exposed file/endpoint - fetch it and assess what it leaks (config, source, credentials, internal detail, metrics).',
        verification: 'The URL returns sensitive content, not a generic 404 or login redirect.',
      };
    case 'Nuclei - default-login':
      return {
        tool: 'Manual credential test',
        command: `Try the documented default credentials for "${opts.name}" at ${opts.matchedAt}`,
        rationale: 'nuclei detected a login panel/product known to ship default credentials - test the handful of documented pairs (not a brute-force).',
        verification: 'A default credential pair authenticates.',
      };
    case 'Nuclei - misconfiguration':
      return { tool: 'None (informational)', command: null, rationale: 'Configuration weakness flagged by nuclei - note for remediation; not independently exploitable without a further primitive.', verification: null };
    case 'Nuclei - other':
      return { tool: 'Manual triage', command: null, rationale: 'nuclei template fired but no deterministic rule maps this class yet - review manually.', verification: null };
    case 'GraphQL - introspection':
      return {
        tool: 'InQL / graphql-cop (schema mapping)',
        command: `inql -t ${opts.endpoint}   # or: graphql-cop -t ${opts.endpoint}`,
        rationale: 'Introspection is enabled - dump the full schema and enumerate every query/mutation, then test each for missing authorization and IDOR (object args like id:, userId:). This is the highest-value next step against a GraphQL API.',
        verification: 'InQL writes the schema and a per-operation request template; at least one query/mutation returns data without authentication.',
      };
    case 'GraphQL - suggestion-leak':
      return {
        tool: 'clairvoyance (schema reconstruction)',
        command: `clairvoyance ${opts.endpoint} -o schema.json`,
        rationale: 'Introspection is off but field-suggestion hints leak type/field names - clairvoyance walks those hints to rebuild most of the schema, then proceed as above.',
        verification: 'clairvoyance produces a schema JSON covering the main query/mutation fields.',
      };
    case 'GraphQL - batching':
      return {
        tool: 'None (note the vector)',
        command: null,
        rationale: 'Array-batched queries execute in one request - this amplifies any rate-limited operation (login, OTP, coupon/gift-card checks). Relevant for a credential or brute-force follow-up; not exploited here (that is availability-adjacent).',
        verification: null,
      };
    case 'GraphQL - get-queries':
      return {
        tool: 'Manual review',
        command: `curl '${opts.endpoint}?query=%7B__typename%7D'`,
        rationale: 'Queries run over GET - if mutations do too, that is a CSRF vector for state-changing operations. Check whether a mutation executes via GET.',
        verification: 'A mutation sent as a GET query string executes.',
      };
    case 'None':
      return { tool: null, command: null, rationale: null, verification: null };
    default:
      return { tool: 'Manual triage', command: null, rationale: 'No deterministic rule defined yet for this finding type - flag for manual review rather than guess a tool.', verification: null };
  }
};

if (ctx.webScan && ctx.webScan.reachable && ctx.webScan.securityHeaders && ctx.webScan.securityHeaders.missing.length) {
  findings.push({
    category: 'Missing Security Headers',
    name: 'Missing Security Headers',
    detail: `Missing on ${ctx.webScan.origin}: ${ctx.webScan.securityHeaders.missing.join(', ')}.`,
    ...dispatch('Missing Security Headers'),
  });
}

if (ctx.webScan && ctx.webScan.contentDiscovery) {
  const hits = ctx.webScan.contentDiscovery.filter(h => h.distinctFromBaseline);
  if (hits.length) {
    const sample = hits.slice(0, 15).map(h => h.path).join(', ');
    findings.push({
      category: 'Content Discovery',
      name: 'Content Discovery - API/Directory Surface',
      detail: `${hits.length} genuine paths discovered on ${ctx.webScan.origin} (sample: ${sample}${hits.length > 15 ? ', ...' : ''}).`,
      ...dispatch('Content Discovery', { origin: ctx.webScan.origin }),
    });
  }
}

if (ctx.sensitiveFileExposures && ctx.sensitiveFileExposures.length) {
  for (const f of ctx.sensitiveFileExposures) {
    findings.push({
      category: 'Exposed Sensitive File',
      name: `Sensitive File: ${f.path}`,
      detail: f.confirmed
        ? `${f.path} confirmed exposed via ${f.source}, HTTP ${f.status}, ${f.length} bytes. Content excerpt already fetched.`
        : `${f.path} flagged by ${f.source} but re-fetch returned ${f.status} not 200 - not confirmed exposed this run. URL: ${f.url}`,
      ...dispatch(f.confirmed ? 'Exposed Sensitive File - confirmed' : 'Exposed Sensitive File - unconfirmed', { url: f.url }),
    });
  }
}

if (ctx.componentFindings && ctx.componentFindings.length) {
  for (const c of ctx.componentFindings) {
    findings.push({
      category: 'Vulnerable Component',
      name: `Vulnerable Component: ${c.component} ${c.version}`,
      detail: `severity ${c.severity}${c.cve && c.cve.length ? ', ' + c.cve.join(', ') : ''}: ${c.summary || 'see info links'}.`,
      ...dispatch('Vulnerable Component', { component: c.component, version: c.version }),
    });
  }
}

if (ctx.sqlmapScan && !ctx.sqlmapScan.skipped) {
  const results = ctx.sqlmapScan.results || [];
  const vulnResults = results.filter(r => r.vulnerable);
  const negResults = results.filter(r => !r.vulnerable);
  for (const r of vulnResults) {
    findings.push({
      category: 'SQL Injection (sqlmap)',
      name: `SQL Injection confirmed by sqlmap: ${r.url}`,
      detail: `Injectable at ${r.url}. Findings: ${(r.findings || []).map(f => `${f.parameter}: ${f.type || 'injectable'}`).join('; ')}.`,
      ...dispatch('SQL Injection - confirmed', { surface: r.url }),
    });
  }
  if (negResults.length) {
    findings.push({
      category: 'SQL Injection (sqlmap)',
      name: 'SQL Injection tested - negative',
      detail: ctx.sqlmapScan.fallbackCrawl
        ? 'sqlmap fell back to a blind homepage crawl (weak test, JS-rendered app) - no injectable parameter found in what it reached.'
        : `Tested ${negResults.length} of ${ctx.sqlmapScan.candidateCount} discovered candidate endpoint(s) (top ${ctx.sqlmapScan.testedCount}, --level=1 --risk=1 each) - no injectable parameters found in any of them.`,
      ...dispatch('SQL Injection - negative'),
    });
  }
}

if (ctx.zapScan && !ctx.zapScan.skipped && ctx.zapScan.reachable && ctx.zapScan.alertCount > 0) {
  const byName = {};
  for (const a of ctx.zapScan.alerts) {
    byName[a.name] = byName[a.name] || { risk: a.risk, urls: [] };
    if (byName[a.name].urls.length < 5) byName[a.name].urls.push(a.url);
  }
  const socketIoOnly = (urls) => urls.length > 0 && urls.every(u => /\/socket\.io\//i.test(u));
  for (const [name, info] of Object.entries(byName)) {
    let zapCategory = 'ZAP - unmapped';
    const contradictedBySqlmap = /sql injection/i.test(name) && info.urls.some(u => sqlmapTestedNegative(u));
    if (/session/i.test(name) && socketIoOnly(info.urls)) zapCategory = 'ZAP - false positive';
    else if (contradictedBySqlmap) zapCategory = 'ZAP - sqli contradicted by sqlmap';
    else if (/sql injection/i.test(name)) zapCategory = 'ZAP - sqli';
    else if (/cross site scripting|xss/i.test(name)) zapCategory = 'ZAP - xss';
    else if (/content security|anti-clickjacking|x-content-type|cookie|header|cross-domain/i.test(name)) zapCategory = 'ZAP - informational';
    findings.push({
      category: 'ZAP Alert',
      name: `ZAP Alert: ${name} (${info.risk})`,
      detail: `URLs: ${info.urls.join(', ')}.${contradictedBySqlmap ? ' sqlmap directly tested this same endpoint/parameter and found no injectable parameter - contradicts this alert.' : ''}`,
      ...dispatch(zapCategory, { url: info.urls[0] }),
    });
  }
}

// Real CVE matches, deduped and exploit-flagged by Build Deterministic
// Report Sections already - consuming that instead of the raw vulners
// citation list avoids re-introducing the duplicate-citation noise problem
// the Section 5 CVE table was fixed for. Research-only (no known exploit)
// CVEs are deliberately skipped here - they're already listed in the
// Section 5 CVE table, and an "attack planning" bullet whose only content
// is "monitor for an exploit landing" adds nothing Section 5 didn't already
// say, for every one of what can be dozens of catalogued-but-unexploited
// CVEs on an old target. They still count toward the executive summary
// (computed independently in Build Deterministic Report Sections from the
// same dedupedCves), just not toward Section 6's per-finding bullets.
for (const c of (ctx.dedupedCves || [])) {
  if (!c.exploitable) continue;
  findings.push({
    category: 'Known CVE',
    name: `CVE: ${c.id} (${c.port}/${c.service})`,
    detail: `Product ${c.product || 'unknown'} ${c.version || ''}, CVSS ${c.cvss}, Known Exploit?: yes.`,
    ...dispatch('Known CVE - exploitable', { id: c.id }),
  });
}

// WordPress findings from wpscan -> deterministic dispatch, same as every
// other category above (keyed on wpscan's structured output, not an LLM
// picking a tool). Only runs when the WordPress branch actually ran.
if (ctx.wpscanScan && ctx.wpscanScan.ran) {
  const wp = ctx.wpscanScan;
  const origin = wp.origin || (ctx.webScan && ctx.webScan.origin) || `http://${ctx.target}`;
  const host = origin.replace(/^https?:\/\//, '').replace(/\/.*$/, '');

  const comps = [];
  if (wp.coreVulns && wp.coreVulns.length) comps.push({ what: `core ${wp.coreVersion || ''}`.trim(), slug: 'wordpress', version: wp.coreVersion || '', vulns: wp.coreVulns });
  if (wp.mainTheme && wp.mainTheme.vulns && wp.mainTheme.vulns.length) comps.push({ what: `theme ${wp.mainTheme.slug} ${wp.mainTheme.version || ''}`.trim(), slug: wp.mainTheme.slug, version: wp.mainTheme.version || '', vulns: wp.mainTheme.vulns });
  for (const pl of (wp.plugins || [])) if (pl.vulns && pl.vulns.length) comps.push({ what: `plugin ${pl.slug} ${pl.version || ''}`.trim(), slug: pl.slug, version: pl.version || '', vulns: pl.vulns });
  for (const comp of comps) {
    // A single old core version can carry 100+ catalogued vulns - dispatch
    // only the ones that are actionable now (public exploit, or at least a
    // CVE id to search), exploit-backed first, capped. Same principle as the
    // nmap-vulners exploitable/research-only split.
    const actionable = comp.vulns
      .filter(v => (v.hasExploit || v.cve) && !v.isDos)
      .sort((a, b) => (b.hasExploit ? 1 : 0) - (a.hasExploit ? 1 : 0) || (b.cvss || 0) - (a.cvss || 0))
      .slice(0, 12);
    for (const v of actionable) {
      findings.push({
        category: 'WordPress Vulnerable Component',
        name: `WordPress ${comp.what}: ${v.title}`,
        detail: `${v.title}${v.hasExploit ? ' - public exploit available' : ''}${v.fixedIn ? ` (fixed in ${v.fixedIn})` : ''}${v.refs && v.refs.length ? ` - ${v.refs.join(', ')}` : ''}.`,
        ...dispatch('WordPress - vulnerable component', { slug: comp.slug, version: comp.version, cve: v.cve, hasExploit: v.hasExploit }),
      });
    }
    if (comp.vulns.length > actionable.length) {
      findings.push({
        category: 'WordPress',
        name: `WordPress ${comp.what}: ${comp.vulns.length - actionable.length} further catalogued vuln(s)`,
        detail: `Listed in the WordPress section above; no public exploit or CVE id to drive an automated next step.`,
        ...dispatch('Known CVE - research-only', { id: comp.what }),
      });
    }
  }

  // Outdated plugins/themes without a name-based CVE match get a searchsploit
  // follow-up rather than being silently dropped (core CVEs come from NVD above).
  const outdatedComps = [];
  if (wp.mainTheme && wp.mainTheme.outdated && !((wp.mainTheme.vulns || []).length)) outdatedComps.push({ kind: 'theme', slug: wp.mainTheme.slug, version: wp.mainTheme.version || '' });
  for (const pl of (wp.plugins || [])) if (pl.outdated && !((pl.vulns || []).length)) outdatedComps.push({ kind: 'plugin', slug: pl.slug, version: pl.version || '' });
  for (const oc of outdatedComps) {
    findings.push({
      category: 'WordPress',
      name: `WordPress ${oc.kind} outdated: ${(oc.slug + ' ' + oc.version).trim()}`,
      detail: `wpscan reports ${oc.slug} ${oc.version} is behind the current release.`,
      ...dispatch('WordPress - outdated component', oc),
    });
  }

  if (wp.xmlrpcEnabled) {
    findings.push({
      category: 'WordPress',
      name: 'WordPress XML-RPC enabled',
      detail: `${origin}/xmlrpc.php is reachable - exposes pingback (server-side request forgery / internal host discovery) and system.multicall (credential-attack amplification).`,
      ...dispatch('WordPress - xmlrpc', { host }),
    });
  }

  if (wp.users && wp.users.length) {
    findings.push({
      category: 'WordPress',
      name: `WordPress users enumerated: ${wp.users.join(', ')}`,
      detail: `Valid usernames recovered via author enumeration: ${wp.users.join(', ')}.`,
      ...dispatch('WordPress - user enum', { origin, users: wp.users.join(',') }),
    });
  }

  for (const url of [...(wp.configBackups || []), ...(wp.dbExports || [])]) {
    findings.push({
      category: 'WordPress',
      name: `WordPress backup/export exposed: ${url}`,
      detail: `wpscan found a web-accessible config backup or database export at ${url}.`,
      ...dispatch('Exposed Sensitive File - unconfirmed', { url }),
    });
  }
}

// Nuclei findings -> deterministic dispatch. CVEs already surfaced by
// nmap-vulners or the WordPress NVD lookup are not dispatched again here.
if (ctx.nucleiScan && ctx.nucleiScan.ran && (ctx.nucleiScan.findings || []).length) {
  const already = new Set();
  for (const cc of (ctx.dedupedCves || [])) if (cc.id) already.add(String(cc.id).toUpperCase());
  if (ctx.wpscanScan && ctx.wpscanScan.ran) for (const v of (ctx.wpscanScan.coreVulns || [])) if (v.cve) already.add(String(v.cve).toUpperCase());

  let pushed = 0;
  let suppressed = 0;
  for (const f of ctx.nucleiScan.findings) {
    if (['info', 'unknown'].includes(f.severity)) continue;
    if (f.cve && already.has(f.cve)) { suppressed++; continue; }
    if (pushed >= 20) { suppressed++; continue; }
    const tags = f.tags || [];
    let cat = 'Nuclei - other';
    if (f.cve) cat = 'Nuclei - cve';
    else if (tags.some(t => /exposure|disclosure|listing|secret|backup/.test(t)) || /exposure|disclosure|listing/.test(f.templateId)) cat = 'Nuclei - exposure';
    else if (tags.some(t => /default-login/.test(t)) || /default-login/.test(f.templateId)) cat = 'Nuclei - default-login';
    else if (tags.some(t => /misconfig/.test(t)) || /misconfig/.test(f.templateId)) cat = 'Nuclei - misconfiguration';
    const hasExploit = tags.some(t => ['kev', 'metasploit', 'exploit'].includes(t));
    findings.push({
      category: 'Nuclei',
      name: `Nuclei: ${f.name}${f.cve ? ' (' + f.cve + ')' : ''}`,
      detail: `${String(f.severity).toUpperCase()} - template \`${f.templateId}\` matched at ${f.matchedAt}${f.cvss ? ', CVSS ' + f.cvss : ''}.`,
      ...dispatch(cat, { cve: f.cve, hasExploit, matchedAt: f.matchedAt, name: f.name }),
    });
    pushed++;
  }
  if (suppressed) {
    findings.push({
      category: 'Nuclei',
      name: `Nuclei: ${suppressed} further finding(s) not individually dispatched`,
      detail: 'Either already covered by another tool above (deduped CVE), below the dispatch cap, or informational - see the Nuclei section for the full list.',
      ...dispatch('None'),
    });
  }
}

// GraphQL findings -> dispatch.
if (ctx.graphql && ctx.graphql.detected) {
  const g = ctx.graphql;
  if (g.introspectionEnabled) {
    findings.push({
      category: 'GraphQL',
      name: `GraphQL introspection enabled: ${g.endpoint}`,
      detail: `Full schema readable without authentication${g.typeCount ? ` (${g.typeCount} types` : ''}${g.hasMutations ? ', mutations present' : ''}${g.typeCount ? ')' : ''}.`,
      ...dispatch('GraphQL - introspection', { endpoint: g.endpoint }),
    });
  } else if (g.suggestionLeak) {
    findings.push({
      category: 'GraphQL',
      name: `GraphQL schema leaks via field suggestions: ${g.endpoint}`,
      detail: 'Introspection is disabled but "Did you mean" hints disclose type/field names.',
      ...dispatch('GraphQL - suggestion-leak', { endpoint: g.endpoint }),
    });
  }
  if (g.batchingEnabled) {
    findings.push({
      category: 'GraphQL',
      name: `GraphQL query batching enabled: ${g.endpoint}`,
      detail: 'Array-batched queries execute in a single request.',
      ...dispatch('GraphQL - batching', { endpoint: g.endpoint }),
    });
  }
  if (g.getQueriesAllowed) {
    findings.push({
      category: 'GraphQL',
      name: `GraphQL accepts queries over GET: ${g.endpoint}`,
      detail: 'Queries execute via GET query string.',
      ...dispatch('GraphQL - get-queries', { endpoint: g.endpoint }),
    });
  }
}

// Discovered but untestable: known auth/login-shaped endpoints found
// during crawling/content-discovery that this platform can't functionally
// test - no credentials to submit, and for JS SPAs the form itself isn't
// server-rendered HTML to fill in even if it did. Flagged explicitly for a
// human to follow up on, every time one is discovered, rather than
// silently dropped or folded into a generic "not run" line - the endpoint
// IS real and found, it's specifically the automated test that's missing.
if (ctx.webScan && ctx.webScan.reachable) {
  const sensitivePathRe = /login|signin|sign-in|auth|register|password|reset|admin/i;
  const testedUrls = new Set(((ctx.sqlmapScan && ctx.sqlmapScan.results) || []).map(r => r.url));
  const candidatePaths = [...new Set(
    (ctx.webScan.contentDiscovery || [])
      .filter(c => c.distinctFromBaseline && sensitivePathRe.test(c.path))
      .map(c => c.path)
  )];
  for (const path of candidatePaths) {
    const url = ctx.webScan.origin + path;
    if (testedUrls.has(url)) continue;
    findings.push({
      category: 'Discovered But Untestable',
      name: `Login/Auth-Shaped Endpoint: ${path}`,
      detail: `Discovered during content discovery/crawling but never functionally tested against real input.`,
      ...dispatch('Discovered But Untestable', { url }),
    });
  }
}

if (!findings.length) {
  findings.push({
    category: 'None',
    name: 'No confirmed findings',
    detail: 'No confirmed vulnerabilities were found this run - state this plainly, no exploit line needed.',
    ...dispatch('None'),
  });
}

return findings.map(f => ({ json: { ...f, target: ctx.target } }));

const items = $input.all();
const bullets = items.map(i => i.json.bulletText).join('\n\n');
const ctx = $('Build Deterministic Report Sections').item.json;
const section6Text = '## 6. If I Were Attacking This\n\n' + (bullets || '(No findings to report.)');

// Condensed, grouped-by-tool summary for Section 7's prompt input - the
// full section6Text repeats a near-identical templated bullet once per CVE
// on a CVE-heavy target (dozens of near-duplicate "use Metasploit for
// CVE-X" lines), which overloaded the model's context window and made
// Section 7 fail to converge to a well-formed answer at all. Section 7
// needs to know what tools/categories are in play to chain into an ATT&CK
// narrative, not read every individual repetition.
const byTool = new Map();
let informationalCount = 0;
for (const it of items) {
  const f = it.json;
  if (!f.tool || /^(None|Manual)/.test(f.tool)) { informationalCount++; continue; }
  if (!byTool.has(f.tool)) byTool.set(f.tool, { tool: f.tool, count: 0, examples: [] });
  const g = byTool.get(f.tool);
  g.count++;
  if (g.examples.length < 3) g.examples.push(f.name);
}
const toolGroups = [...byTool.values()];
const section6Summary = toolGroups.length
  ? toolGroups.map(g => `- ${g.tool}: ${g.count} finding(s), e.g. ${g.examples.join('; ')}`).join('\n') + (informationalCount ? `\n- ${informationalCount} additional informational/no-action finding(s) not independently actionable.` : '')
  : 'No actionable findings this run.';

// Deterministic layer triggers for Section 7 - additive per-host layers
// (network/OS always runs; middleware/technology only if a product was
// actually identified; webapp/API only if there was real content), not an
// LLM guess at which stages are relevant. Section 7 is only allowed to
// narrate the layers this flags as triggered, never invent additional ones.
const networkLayerTriggered = !!(ctx.portScan && !ctx.portScan.skipped && ctx.portScan.openPorts.length);
const identifiedProducts = networkLayerTriggered
  ? [...new Set(ctx.portScan.openPorts.filter(o => o.product).map(o => `${o.product}${o.version ? ' ' + o.version : ''} (port ${o.port})`))]
  : [];
const middlewareLayerTriggered = identifiedProducts.length > 0;
const webappLayerTriggered = !!(ctx.webScan && ctx.webScan.reachable && ((ctx.webScan.contentDiscovery || []).some(h => h.distinctFromBaseline) || (ctx.webScan.forms || []).length));
const layerTriggers = { networkLayerTriggered, middlewareLayerTriggered, identifiedProducts, webappLayerTriggered };

return [{ json: { ...ctx, section6Text, section6Summary, layerTriggers } }];

const ctx = $json;
const findings = ctx.componentFindings || [];
const results = [];
const MAX = 15;
let checked = 0;
for (const c of findings) {
  if (checked >= MAX) break;
  if (!c.component || !c.version) continue;
  checked++;
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.osv.dev/v1/query',
      body: { version: c.version, package: { name: c.component, ecosystem: 'npm' } },
      json: true,
      timeout: 8000,
    });
    const vulns = (res && res.vulns) || [];
    results.push({
      component: c.component,
      version: c.version,
      retireCve: c.cve || [],
      osvMatchCount: vulns.length,
      osvVulns: vulns.slice(0, 5).map(v => ({
        id: v.id,
        aliases: v.aliases || [],
        summary: v.summary || (v.details ? v.details.slice(0, 200) : null),
        severity: (v.severity && v.severity[0] && v.severity[0].score) || null,
      })),
      newFindingsBeyondRetire: vulns.some(v => {
        const ids = [v.id, ...(v.aliases || [])];
        return !ids.some(id => (c.cve || []).includes(id));
      }),
      lookupStatus: 'ok',
    });
  } catch (e) {
    results.push({ component: c.component, version: c.version, retireCve: c.cve || [], lookupStatus: 'failed', error: String(e.message || e).slice(0, 200) });
  }
}
return [{ json: { ...ctx, osvEnrichment: results } }];

const ctx = $json;
const target = ctx.target;
const isIp = ctx.isIp;
const resolveLine = isIp
  ? `IP="${target}"`
  : `IP=$(dig +short ${target} A | grep -E '^[0-9]+\\.' | tail -n1)`;
const cmd = `
${resolveLine}
echo "IP:$IP"
if [ -n "$IP" ]; then
  REV=$(echo "$IP" | awk -F. '{print $4"."$3"."$2"."$1}')
  ORIGIN=$(dig +short "$REV.origin.asn.cymru.com" TXT | tr -d '"')
  echo "ORIGIN:$ORIGIN"
  ASN=$(echo "$ORIGIN" | cut -d'|' -f1 | tr -d ' ')
  if [ -n "$ASN" ]; then
    ASNAME=$(dig +short "AS$ASN.asn.cymru.com" TXT | tr -d '"')
    echo "ASNAME:$ASNAME"
  fi
fi
echo "CNAME:"
${isIp ? '' : 'dig +short ' + target}
`;
return [{ json: { ...ctx, command: cmd } }];

const ctx = $('Build Attribution Commands').item.json;
const out = $json.stdout || '';
const lines = out.split('\n');
let ip = null, originLine = null, asName = null;
const cnameChain = [];
let inCname = false;
for (const raw of lines) {
  const t = raw.trim();
  if (!t) continue;
  if (t.startsWith('IP:')) { ip = t.slice(3).trim() || null; continue; }
  if (t.startsWith('ORIGIN:')) { originLine = t.slice(7).trim() || null; continue; }
  if (t.startsWith('ASNAME:')) { asName = t.slice(7).trim() || null; continue; }
  if (t === 'CNAME:') { inCname = true; continue; }
  if (inCname) { cnameChain.push(t); continue; }
}

let asn = null, country = null;
if (originLine) {
  const parts = originLine.split('|').map(p => p.trim());
  asn = parts[0] || null;
  country = parts[2] || null;
}
let orgName = null;
if (asName) {
  // Cymru's AS-name TXT format: "<asn> | <country> | <registry> | <date> | <org name>, <cc>"
  const parts = asName.split('|').map(p => p.trim());
  orgName = parts[parts.length - 1] || null;
}

const orgLower = (orgName || '').toLowerCase();
let cloudProvider = 'other/unknown';
if (/microsoft|azure/.test(orgLower)) cloudProvider = 'Azure';
else if (/amazon|aws/.test(orgLower)) cloudProvider = 'AWS';
else if (/google/.test(orgLower)) cloudProvider = 'GCP';
else if (/cloudflare/.test(orgLower)) cloudProvider = 'Cloudflare';
else if (/rackspace/.test(orgLower)) cloudProvider = 'Rackspace';

// Best-effort Azure region extraction from a cloudapp.azure.com-style
// hostname in the CNAME chain - not always present, only when there's an
// actual public Azure Traffic Manager/App Service style CNAME trail.
let azureRegion = null;
let hostingModelHint = null;
for (const h of cnameChain) {
  const m = h.match(/\.([a-z0-9]+)\.cloudapp\.azure\.com\.?$/i);
  if (m) azureRegion = m[1];
  if (/\.azurewebsites\.net\.?$/i.test(h)) hostingModelHint = 'Azure App Service (CNAME trail confirmed)';
  if (/\.trafficmanager\.net\.?$/i.test(h)) hostingModelHint = (hostingModelHint ? hostingModelHint + '; ' : '') + 'Azure Traffic Manager in chain';
}

const attribution = {
  resolvedIp: ip,
  asn, asnOrgName: orgName, asnCountry: country,
  cloudProvider, azureRegion, hostingModelHint,
  cnameChain,
};
return [{ json: { ...ctx, attribution } }];

const ctx = $json;
const target = ctx.target;
const has443 = ctx.portScan && !ctx.portScan.skipped && ctx.portScan.openPorts.some(p => p.port === 443);
if (!has443) {
  return [{ json: { ...ctx, command: "echo 'SKIPPED'", tlsAttempted: false } }];
}
// --fast skips exhaustive per-cipher enumeration (the slowest phase) - confirmed
// live: default mode didn't reach the cert/SAN data within 240s against a
// real modern target (google.com, large cipher/cert profile); --fast within
// 180s reached cert data plus nearly every other section.
const command = `timeout 180 testssl.sh --quiet --color 0 --fast --jsonfile-pretty=/tmp/testssl-out-${Date.now()}.json ${target}:443 >/dev/null 2>&1; cat /tmp/testssl-out-*.json 2>/dev/null | tail -c 400000 || echo '{}'`;
return [{ json: { ...ctx, command, tlsAttempted: true } }];

const ctx = $('Build TLS Scan Command').item.json;
if (!ctx.tlsAttempted) {
  return [{ json: { ...ctx, tlsScan: { skipped: true, reason: 'port 443 not open' } } }];
}
// testssl.sh's --jsonfile-pretty output is a nested object, not a flat array:
// { ..., scanResult: [ { targetHost, ip, port, pretest: [...], protocols: [...],
// ciphers: [...], serverDefaults: [...], vulnerabilities: [...], ... } ] } -
// each named key under scanResult[0] is a section holding an array of finding
// objects. Flatten every section's array together rather than assuming a
// single top-level array (confirmed live against a real target - the naive
// flat-array assumption silently produced zero findings).
let allEntries = [];
try {
  const parsed = JSON.parse($json.stdout || '{}');
  const scanResult = (parsed.scanResult && parsed.scanResult[0]) || {};
  for (const section of Object.values(scanResult)) {
    if (Array.isArray(section)) allEntries.push(...section);
  }
} catch (e) { allEntries = []; }

const notableSeverities = new Set(['LOW', 'MEDIUM', 'HIGH', 'CRITICAL']);
// cert_subjectAltName's real id carries a per-certificate suffix (e.g.
// "cert_subjectAltName <hostCert#1>" - a target can present multiple certs,
// RSA + EC dual-cert setups are common) - match by prefix, not exact equality.
const findings = allEntries
  .filter(e => e.severity && notableSeverities.has(e.severity) && !String(e.id || '').startsWith('cert_subjectAltName'))
  .map(e => ({ id: e.id, severity: e.severity, finding: e.finding, cve: e.cve || null }));

const sanEntry = allEntries.find(e => String(e.id || '').startsWith('cert_subjectAltName'));
const certSans = sanEntry
  ? sanEntry.finding.split(/[\s,]+/).map(s => s.trim()).filter(Boolean)
  : [];

const tlsScan = { skipped: false, ranButNoOutput: allEntries.length === 0, findingCount: findings.length, findings, certSans };
return [{ json: { ...ctx, tlsScan } }];

const item = $('Split Findings').item.json;
let body;
if (item.tool && !/^(None|Manual)/.test(item.tool)) {
  body = `1. **Tool/command**: \`${item.command}\`\n2. **Goal**: ${item.rationale}\n3. **Verification signal**: ${item.verification || 'No deterministic verification signal defined yet for this category.'}`;
} else {
  body = item.rationale || 'No action - see detail above.';
}
const bulletText = `### ${item.name}\n${body}`;
return [{ json: { ...item, bulletText } }];

const ctx = $json;
const ws = ctx.webScan;
if (!ws || !ws.reachable) {
  return [{ json: { ...ctx, webScan: { ...(ws || {}), wordpress: { detected: false, reason: 'web target not reachable' } } } }];
}
const origin = ws.origin;
const httpGet = async (path) => {
  try {
    return await this.helpers.httpRequest({ method: 'GET', url: origin + path, timeout: 10000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  } catch (e) { return null; }
};

const evidence = [];
let version = null;
const fpStrings = (ws.fingerprint && ws.fingerprint.evidenceStrings) || [];
for (const s of fpStrings) {
  if (/wp-content|wp-includes/i.test(s)) evidence.push('crawl evidence: ' + s.slice(0, 120));
  const gen = s.match(/generator[^"']*WordPress\s*([0-9.]+)?/i);
  if (gen) { evidence.push('generator string: ' + s.slice(0, 120)); if (gen[1]) version = version || gen[1]; }
}
const headers = ws.headers || {};
const linkHdr = String(headers['link'] || headers['Link'] || '');
if (/api\.w\.org/i.test(linkHdr)) evidence.push('Link header advertises WP REST API (api.w.org)');
if (headers['x-pingback'] || headers['X-Pingback']) evidence.push('X-Pingback header present');
for (const c of (ws.contentDiscovery || [])) {
  if (/^\/(wp-login\.php|wp-admin|xmlrpc\.php|wp-json)/i.test(c.path) && c.distinctFromBaseline) evidence.push('content-discovery hit: ' + c.path);
}

const restRoot = await httpGet('/wp-json/');
if (restRoot && restRoot.statusCode === 200) {
  const body = typeof restRoot.body === 'string' ? restRoot.body : JSON.stringify(restRoot.body || {});
  if (/"namespaces"|"routes"|"name":/.test(body)) evidence.push('/wp-json/ returns a WP REST API index (HTTP 200)');
}
const login = await httpGet('/wp-login.php');
if (login && /user_login|loginform|wp-submit/.test(typeof login.body === 'string' ? login.body : '')) {
  evidence.push('/wp-login.php serves the standard WordPress login form');
}

if (!version) {
  const readme = await httpGet('/readme.html');
  if (readme && typeof readme.body === 'string') {
    const m = readme.body.match(/Version\s+([0-9]+\.[0-9]+(?:\.[0-9]+)?)/i);
    if (m) { version = m[1]; evidence.push('/readme.html discloses version ' + m[1]); }
  }
}
if (!version) {
  for (const s of fpStrings) {
    const m = s.match(/wp-(?:includes|admin)\/[^"'\s]*\?ver=([0-9]+\.[0-9]+(?:\.[0-9]+)?)/i);
    if (m) { version = m[1]; break; }
  }
}

const detected = evidence.length >= 2 || fpStrings.some(s => /wp-content|wp-includes/i.test(s));
return [{ json: { ...ctx, webScan: { ...ws, wordpress: { detected, version: version || null, evidence: evidence.slice(0, 12) } } } }];

const ctx = $json;
const ws = ctx.webScan;
if (!ws || !ws.reachable) {
  return [{ json: { ...ctx, graphql: { detected: false, reason: 'web target not reachable' } } }];
}
const origin = ws.origin;
const req = async (opts) => {
  try { return await this.helpers.httpRequest({ timeout: 10000, returnFullResponse: true, ignoreHttpStatusErrors: true, ...opts }); }
  catch (e) { return null; }
};

// 1. locate a GraphQL endpoint
const candidates = ['/graphql', '/api/graphql', '/v1/graphql', '/query', '/graphiql', '/graphql/console', '/api'];
let endpoint = null, probeBody = null;
for (const path of candidates) {
  const r = await req({ method: 'POST', url: origin + path, body: { query: '{__typename}' }, json: true });
  if (!r) continue;
  const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || {});
  if (/"data"\s*:\s*\{[^}]*"__typename"/.test(body) || (/"errors"/.test(body) && /(GraphQL|Cannot query|Syntax Error|must provide query)/i.test(body))) {
    endpoint = origin + path;
    probeBody = body.slice(0, 400);
    break;
  }
}
if (!endpoint) {
  return [{ json: { ...ctx, graphql: { detected: false } } }];
}

const evidence = [];
const findings = { detected: true, endpoint, evidence };

// 2. introspection
const INTROSPECT = '{"query":"query{__schema{queryType{name} mutationType{name} types{name kind}}}"}';
const ir = await req({ method: 'POST', url: endpoint, headers: { 'content-type': 'application/json' }, body: INTROSPECT });
const irBody = ir && (typeof ir.body === 'string' ? ir.body : JSON.stringify(ir.body || {}));
if (irBody && /"__schema"\s*:\s*\{/.test(irBody)) {
  findings.introspectionEnabled = true;
  try {
    const j = JSON.parse(irBody);
    const s = j.data.__schema;
    findings.typeCount = (s.types || []).filter(t => t.name && !t.name.startsWith('__')).length;
    findings.queryType = s.queryType && s.queryType.name;
    findings.mutationType = s.mutationType && s.mutationType.name;
    findings.hasMutations = !!s.mutationType;
  } catch (e) { /* keep the boolean */ }
  evidence.push(`introspection enabled - full schema readable (${findings.typeCount || '?'} types)`);
} else {
  findings.introspectionEnabled = false;
  // 3. field-suggestion leak (schema disclosure with introspection off)
  const sr = await req({ method: 'POST', url: endpoint, headers: { 'content-type': 'application/json' }, body: '{"query":"{ __typenamex }"}' });
  const srBody = sr && (typeof sr.body === 'string' ? sr.body : JSON.stringify(sr.body || {}));
  if (srBody && /Did you mean/i.test(srBody)) {
    findings.suggestionLeak = true;
    evidence.push('introspection disabled, but field-suggestion hints ("Did you mean") leak schema names');
  }
}

// 4. GET-based queries (CSRF surface)
const gr = await req({ method: 'GET', url: endpoint + '?query=' + encodeURIComponent('{__typename}') });
const grBody = gr && (typeof gr.body === 'string' ? gr.body : JSON.stringify(gr.body || {}));
if (grBody && /"data"\s*:\s*\{[^}]*"__typename"/.test(grBody)) {
  findings.getQueriesAllowed = true;
  evidence.push('accepts queries over GET - CSRF surface for state-changing operations if mutations run over GET too');
}

// 5. query batching (rate-limit / brute-force amplification)
const br = await req({ method: 'POST', url: endpoint, headers: { 'content-type': 'application/json' }, body: '[{"query":"{__typename}"},{"query":"{__typename}"}]' });
const brBody = br && (typeof br.body === 'string' ? br.body : JSON.stringify(br.body || {}));
if (brBody && (brBody.match(/"__typename"/g) || []).length >= 2) {
  findings.batchingEnabled = true;
  evidence.push('array-batched queries execute - amplifies any rate-limited operation (login, OTP, coupon checks)');
}

return [{ json: { ...ctx, graphql: findings } }];
